 Reserved"};resource rCDEVFlags (1) {	wantBoot+wantHit+wantInit+		wantCreate+wantAbout+		wantRect+wantClose,			// CDEV flags	1,								//	enabled = True	1,								//	Version = 1	1,								//	Machine = v1 ROMs or higher	5,								//	System = v5.0 or higher	{0,0,20,290},					//	DataRect - top left MUST be 0,0	"SetStart",						//	Name	"Greg Branche",					//	Author	VERSION;						//	Version String};resource rAlertString (1) {	"2"								//	60-character display window	"3"								//	use the NOTE icon	"/"								//	separator character	"I can’t open my data file!"	//	the error message	"/"	"^Bummer!"						//	button title	"\$00"							//	terminator};resource rAlertString (2) {	"3"								//	110-character display window	"3"								//	use the NOTE icon	"/"								//	separator character	"I can’t find the current application! "	//	the error message	"Try using the “Select Application…” option."	"/"	"^Uncool!"						//	button title	"\$00"							//	terminator};resource rAlertString (3) {	"2"								//	60-character display window	"3"								//	use the NOTE icon	"/"								//	separator character	"Can’t load the Standard File tool set."	//	the error message	"/"	"^Bummer!"						//	button title	"\$00"							//	terminator};resource rPString (75, noCrossBank) {	"Please select start application:"};resource rControlList(1) {{	1,		// pop-up menu	$C1,	// first checkbox = Show startup icons	$C2		// second checkbox = Enable programmer CDAs}};resource rControlTemplate (1) {		//	Popup menu		1,							// ID		{3,5,16,285},				// rect		PopUpControl {{				// ProcRef			fType2PopUp,			// flags			fCtlProcNotPtr+RefIsResource+$0080,	// moreFlags ($80 is pop-down triangle)			0,						// refcon			0, /* 76 */				// titleWidth			1,						// menuRef			1						// initialValue		}}};resource rControlTemplate ($C1) {       $000000C1,				// ID       { 21, 54, 30, 285 },		// rect       checkControl {{               $0000,			// flag               $3002,			// moreFlags               $00000000,		// refCon               $C1,				// titleRef               $0000			// initialValue       }};};resource rControlTemplate ($C2) {       $000000C2,				// ID       { 34, 54, 43, 285 },		// rect       checkControl {{               $0000,			// flag               $3002,			// moreFlags               $00000000,		// refCon               $C2,				// titleRef               $0000			// initialValue       }};};resource rPString($C1) { "Show startup icons" };resource rPString($C2) { "Enable programmer CDAs" };resource rControlTemplate (2) {	//	"Out of order" control		1,							// ID		{3,1,32,195},				// rect		StatTextControl { {			// procRef			0,						// flag			FctlProcNotPtr+RefIsResource, // moreFlags			0,						// refCon			2						// textRef		}}};resource rTextForLETextBox2 (2) {	//	Out of order static text	"We are experiencing technical difficulties. "	"Please stand by..."};resource rMenu (1) {	1,								// menu ID	RefIsResource*menuTitleRefShift+RefIsResource*ItemRefShift+fAllowCache,	50,								// ID of title string	{		1,3,4						// IDs of items	};};resource rPString (50, noCrossBank) {	" Start up with: "};resource rMenuItem (1) {	1,	"", "",	18,	RefIsResource*ItemTitleRefShift+rMIItalic,	1};resource rPString (1, noCrossBank) {	"Finder"};resource rMenuItem (3) {	3,	"", "",	0,	RefIsResource*ItemTitleRefShift,	3};resource rPString (3) {	"Current Application"};resource rMenuItem (4) {	4,	"", "",	0,	RefIsResource*ItemTitleRefShift,	4};resource rPString (4, noCrossBank) {	"Select Application…"};resource rControlTemplate (100) {	//	About box control		1,							// ID		{38,5,138,280},				// rect		StatTextControl { {			// procRef			0,						// flag			FctlProcNotPtr+RefIsResource, // moreFlags			0,						// refCon			100						// textRef		}}};resource rTextForLETextBox2 (100) {	//	About box text	"This control panel lets you choose what application will "	"start up automatically when you start (boot) your "	"Apple IIgs."	"\$0D\$0D"	"The checkboxes let you control whether icons appear while "	"the computer is starting up, and whether Classic Desk "	"Accessories such as Visit Monitor and Memory Peeker appear."};resource rIcon (1) {				//	the "CDEV" icon	0x8000,							//	kind	20,								//	height	28,								//	width	$"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	$"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	$"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	$"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	$"FFFFFFFFFFFFFFFFFF22222222FF"	$"FFFFFFFFFFFFFFFFF2222222222F"	$"FFFFFFFFFFFFFFFFF0002222222F"	$"FFFFFFFFFFFFFFFF22222222222F"	$"FFFFFFFFFFFFFFF200222222222F"	$"FFFFFFFFFFFFFF0222022222222F"	$"FFFFFFFFFFFF022022222222222F"	$"FFFF22220202022202222222222F"	$"FFF222220202202222222222222F"	$"FF2222222222222222222222222F"	$"F22222222222222222222222222F"	$"F00000000000000000000000000F"	$"FF0000000000000FFFF00000000F"	$"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	$"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	$"FFFFFFFFFFFFFFFFFFFFFFFFFFFF",	$"0000000000000000000000000000"	$"0000000000000000000000000000"	$"0000000000000000000000000000"	$"0000000000000000000000000000"	$"000000000000000000FFFFFFFF00"	$"00000000000000000FFFFFFFFFF0"	$"00000000000000000FFFFFFFFFF0"	$"0000000000000000FFFFFFFFFFF0"	$"000000000000000FFFFFFFFFFFF0"	$"00000000000000FFFFFFFFFFFFF0"	$"000000000000FFFFFFFFFFFFFFF0"	$"0000FFFFFFFFFFFFFFFFFFFFFFF0"	$"000FFFFFFFFFFFFFFFFFFFFFFFF0"	$"00FFFFFFFFFFFFFFFFFFFFFFFFF0"	$"0FFFFFFFFFFFFFFFFFFFFFFFFFF0"	$"0FFFFFFFFFFFFFFFFFFFFFFFFFF0"	$"00FFFFFFFFFFFFF0000FFFFFFFF0"	$"0000000000000000000000000000"	$"0000000000000000000000000000"	$"0000000000000000000000000000"};